(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[427],{1635:(a,e,d)=>{"use strict";d.d(e,{Az:()=>i,Kn:()=>g,f_:()=>o,e2:()=>l,uw:()=>r,kR:()=>m});var t=d(5494);let s=JSON.parse('[{"slug":"levent-alpoge-rh-proof","title":"Alp\xf6ge与Claude的黎曼猜想声明：形式核验进行中","summary":"Alp\xf6ge公布与Claude合作的黎曼猜想及GRH证明：四页说明加14个Lean分卷。MIT核验175,187个模块编译并重验通过，两套独立内核确认题面定理，但端到端Comparator未跑完，克雷研究所仍列为未解。关键提升链选择归给Claude，完整推导未公开。","format":"magazine","added":"2026-11-21","tags":["AI","黎曼猜想","Lean形式化验证","Claude","AI数学","GRH"],"studioId":"30438609b69d29d9f2ec4998090be78138f9832e2984fc38ee0484368d038c41"},{"slug":"nvidia-investigation-case-files","title":"威胁辱骂与和解：黄仁勋羞辱员工19案调查档案","summary":"纽约时报调查档案卡：整理19起黄仁勋羞辱员工案例，分暴力威胁、当众羞辱、私人贬损、权力机制与和解四类；含“新员工六个月成人礼”、取消一对一会议的控制逻辑及逾百万美元保密和解。多源自员工与匿名知情者，部分有笔记录音佐证，黄仁勋否认。","format":"magazine","added":"2026-11-21","tags":["思想与人文","英伟达","黄仁勋","职场霸凌","纽约时报调查","公司治理"],"studioId":"c04d70e7b41882a3dcb982f11f633e01c388f89ee0e5bccb5c0da80367742535"},{"slug":"nvidia-management-investigation","title":"羞辱式管理：纽约时报调查黄仁勋与英伟达文化","summary":"整理自纽约时报特稿：黄仁勋数十年以公开羞辱为管理手段，“金钱失效后靠羞辱压榨产出”；2005年逾百万美元保密和解、多起诉讼与员工投诉被指未获HR处理；2026年11月其因丑闻辞职，董事会拒绝复职并启动内部调查。报道含匿名信源，英伟达否认指控。","format":"magazine","added":"2026-11-21","tags":["思想与人文","英伟达","黄仁勋","职场霸凌","公司治理","纽约时报"],"studioId":"e9450e6d502d58c2e871019181fbbc4a10a75b60877ec53b9f06e7434171446f"},{"slug":"gemini-path-to-agi","title":"Gemini与通向AGI之路：产品闭环、RSI与可监测安全","summary":"DeepMind高级副总裁Koray对谈：AGI以真实产品闭环为试金石而非静态榜单；Gemini架构是持续迭代的“漏斗”；递归自我改进已分散落地于研发流水线；安全上保持思维链未过滤、多智能体可观察，并联合外部审计。为官方访谈转述，非独立评测。","format":"magazine","added":"2026-11-20","tags":["AI","Google DeepMind","AGI","Gemini","递归自我改进","AI安全"],"studioId":"a6692b338543856b576313f22d369f1ea44a12c56a059af7d99cab2565f66987"},{"slug":"travis-kalanick-on-jensen-huang","title":"卡兰尼克谈舆论战防御与创始人回归NVIDIA","summary":"Uber前CEO卡兰尼克TBPN访谈：应对有组织舆论战的三原则与“战情室”策略；反对职业经理人掌舵，主张黄仁勋以公开表态、代理权投票、员工罢工三步回归NVIDIA；并谈及人类应驾驭AI、其矿业与匹兹堡机器人工厂布局。均为受访者观点，非事实结论。","format":"magazine","added":"2026-11-20","tags":["思想与人文","舆论战","创始人治理","NVIDIA","AI观点","卡兰尼克"],"studioId":"9864820e79e9d935eb9c5de9dc16466f0988cf6d91ea4c2e15ba95daf6d45528"},{"slug":"ethan-mollick-ai-management","title":"人机共生：智能体时代的主体性与团队级AI管理法","summary":"沃顿教授Mollick访谈：智能体可自主运行17小时以上，应从外包转向主动增强。要点：点子廉价、执行是壁垒；领域深度与品味是护城河；管理AI如带团队，设汇报节点、选择点与苏格拉底式追问；在写作等关键环节保留合意困难，琐碎事务果断去技能化。","format":"magazine","added":"2026-11-19","tags":["AI","Ethan Mollick","AI智能体","人机协作","品味护城河","认知外包"],"studioId":"3b2b24a911c85bbb44530c20f06919b450c66d4ab2140262b13cfd5d021357f4"},{"slug":"software-architecture","title":"软件架构指南：共同理解、内部质量与去中心化演进","summary":"Fowler与Johnson的架构观：架构是资深开发者对系统设计的共同理解，关乎重要之事；应用边界是社会建构，企业架构宜去中心化协调；高内部质量能加速交付，回报以周计。附微服务、微前端、绞杀者模式等八项模式与五大组织演进支柱。","format":"magazine","added":"2026-11-19","tags":["工程技术","软件架构","Martin Fowler","微服务","企业架构","内部质量"]},{"slug":"gemini-4-neon-digital-print-magazine","title":"Gemini 4 Neon发布：评测第三，价格为旗舰四成","summary":"谷歌11月18日发布Gemini 4 Neon：综合智能指数61分排第三，价格仅为GPT-6.2与Claude旗舰的37.5%；编程智能体与办公评测登顶，同族Carbon、Hydrogen、Argon各有定位，主打智能体工作流下的低成本与高速度。","format":"magazine","added":"2026-11-19","tags":["AI","Gemini","大模型评测","API定价","智能体","谷歌"]},{"slug":"community-referrals","title":"社群返佣与传销的边界：两级计酬判准与合规底线","summary":"以“付费进群+单层20%返佣”为例拆解社群分销与传销边界：计酬止于两级即合法，三层以上且总人数超30人触刑事红线；另列准入门槛、利润来源、退货与宣传等五维判准、三类灰色雷区及四条实操底线，并注明落地前需结合当地市场监管评估。","format":"magazine","added":"2026-11-18","tags":["思想与人文","传销认定","社群分销","计酬层级","合规治理","法律风险"]},{"slug":"math-journals","title":"我们还需要数学期刊吗：五项功能的拆解与替代","summary":"CNRS研究主任Goldman主张拆解数学期刊容器：传播、登记、验证、筛选、声望五项功能可由arXiv与公开评议承接，但审稿人力与评价归属仍缺替代；作者称更信任大模型核查属个人判断，风险待验。","format":"magazine","added":"2026-11-18","tags":["思想与人文","学术出版","预印本","同行评审","科研评价","AI核查"]},{"slug":"emacs","title":"魔法时代的 Emacs：AI 冲击与软件自由的反讽","summary":"HN 热帖综述：AI 令代码重构成本归零，Emacs 社区遭遇冲击——代码平权、极客优势消解、空谈终结、软件个人化，以及对软件自由的终极反讽：AI 实现了斯托曼“计算机按你想象运行”的梦想，代价是无人理解底层代码。结论：用 API 隔离 AI 模块，保留确定性工具与人工审查。","format":"magazine","added":"2026-11-12","tags":["思想与人文","Emacs","AI编程","自由软件","Hacker News"]},{"slug":"strogatz-big-math","title":"大数学时代：运行世界的隐藏代码","summary":"Strogatz 新书《大数学》节选：数学正从人脑小问题跃向数十亿未知数的宏大系统，支撑推荐引擎、物流与量子计算。书中讲 Barzilay 造出提前五年预警乳腺癌的 Mirai，也讨论机器超越创造者后的黑箱之问：理解重要还是救命重要。结论：驾驭大数学并学会驰骋其上。","format":"magazine","added":"2026-11-11","tags":["思想与人文","数学","书摘","AI","科学人文"]},{"slug":"figma-finance-ai","title":"AI 如何把 Figma 财务团队变成构建者","summary":"a16z 访 Figma CFO：AI 正把财务从对账报表转向构建工具、参与决策。五判断：先做原型再交系统团队托管；指标口径比工具更基础；核心系统购买、业务工作流自建；AI 产出须提交者负责；招聘重业务判断而非 AI 熟练度。AI 是杠杆而非替代品，懂业务能判断的人影响更大。","format":"magazine","added":"2026-11-10","tags":["AI","财务","CFO","a16z"]},{"slug":"lenny-tulsee-doshi","title":"为什么产品经理突然又变得极具价值","summary":"播客访 Gemini 产品总监 Doshi：当人人能用 AI 建造，辨别值得做什么、定义品味与建立秩序成为 PM 的稀缺壁垒。三特质：天天把玩模型懂其 Vibe、亲手写 Eval、每两周推翻路线图。另谈 60-20-20 前瞻矩阵、定期清空技能库防外壳束缚。","format":"magazine","added":"2026-11-10","tags":["AI","产品经理","AI产品","Eval","播客"]},{"slug":"grok-bot-38-uses","title":"Grok Bot 终极指南：38 项功能全解","summary":"Grok Bot 38 项功能全解：入门篇有导入记忆、招募子 Agent、收件箱摘要；进阶篇有云端静默例程、演示教学、转确定性代码省额度、多 Bot 群聊、事件触发器；高阶篇有支付授权、Claude Code 桥接、中央主机、模板市场。核心：幕僚长统筹 Agent 团队。","format":"magazine","added":"2026-11-10","tags":["AI","Grok","AI Agent","自动化","教程"],"studioId":"2e238872c44e39ab3e84499d30ec09ec4518ebe25b39231f9de6587d1456859b"},{"slug":"scientific-problems","title":"如何选择一个好的科学问题","summary":"Uri Alon 论如何选好的科学问题：以可行性与趣味性两维度画帕累托前沿——低年级生先做易课题攒信心，博士后奔右上象限，新 PI 可拆解宏大挑战。要区分外界喧哗与内心微声，用三个试金石检验真兴趣；实验室规定新人前三个月不得定题，先读、议、想。前期多花一周，后期省数月挫败。","format":"magazine","added":"2026-11-10","tags":["个人发展","科研方法","课题选择","研究生培养"]},{"slug":"deepseek-harness-overview","title":"DeepSeek Harness 综述：一切皆插件的智能体 OS","summary":"DSH 综述：开源跨端的智能体底座，理念“一切皆插件”。2026 年 8 月上线，11 月发布 Creator Mode 对话生成插件；11 月初日活约 154 万、日耗 92 万亿 token、插件约 3.5 万个。方向是从插件生态走向常在线、多任务的超级智能体系统。","format":"magazine","added":"2026-11-09","tags":["AI","DeepSeek","智能体","插件生态","开源"],"studioId":"42a27185bfc38313e77943459932cee44bfa92eed73b93fda7dc68d2f41ab000"},{"slug":"hn-briefing","title":"HN 热点简报 2026-11-08：Mac 隐私图谱与刷榜现形","summary":"2026-11-08 HN 简报：macOS 隐藏库明文存个人图谱含亲属打分；MaxxBench 微调题目令模型刷分现形；Claude Code 密码泄密涉千余份公开文件。软件侧 Discord 用 Rust 重写、Asahi 转 GPL；科学侧古 DNA 坐实哥特人北欧起源。","format":"poster","pages":2,"added":"2026-11-08","tags":["AI","Hacker News","科技简报","隐私","开源"]},{"slug":"hn-summary-20261108","title":"HN 热点简报 2026-11-08：暗盒图谱与缩放霸权","summary":"2026-11-08 HN 简报：macOS 隐藏库明文存个人图谱含亲属打分；MaxxBench 微调题目令模型刷分现形；微软 AI Frontiers 因只做缩放解散；Discord 用 Rust 重写，Asahi 转 GPL。","format":"poster","pages":2,"added":"2026-11-08","tags":["AI","Hacker News","科技简报","隐私","开源"]},{"slug":"mail-cuts-20261108","title":"科技剪报 2026-11-08：算力园区的供电设计","summary":"剪报聚焦算力供电：乌兰察布银河园区以风电储能“源网荷储”和 800V 直流，造价约为美国同类五分之一；SpaceXAI 在亚利桑那规划 6GW 园区，电网投入 36 亿美元。结论：算力竞争已深入供电与储能调度。","format":"magazine","added":"2026-11-08","tags":["工程技术","算力基建","数据中心","供电架构","科技剪报"]},{"slug":"llm-voice","title":"LLM Voice：LLM 文体的恐怖谷","summary":"Martin Fowler 论“LLM 文体的恐怖谷”：察觉 AI 腔调时阅读欲即刻萎缩，检测工具不可靠也问错问题；有些“AI 腔”只是代际差异。核心忠告：别让 LLM 写初稿，AI 至多用于大纲和搜索。写作即思考，外包写作即外包思考。例外：疾病辅助、翻译、写给流程的公文。","format":"deck","pages":11,"added":"2026-11-07","tags":["内容创作","写作","AI","文风"]},{"slug":"llm-voice-magazine","title":"LLM 之声：Martin Fowler 论 AI 文体的恐怖谷","summary":"Martin Fowler 警惕“LLM 之声”：对 AI 腔调的排斥是生理性直觉，检测工具无意义；AI 代写初稿的机械腔调极难清除，AI 只可用于大纲和搜索（须核实出处）。写作即思考，外包写作即交出思考。例外：医疗辅助、跨语言沟通、无人读的公文。人性必须从文字中透出。","format":"magazine","added":"2026-11-07","tags":["内容创作","写作","LLM","文风"]},{"slug":"dankoe-fix-life","title":"一日重构一生：Dan Koe 的 24 小时重置协议","summary":"Dan Koe 的 24 小时人生重置协议：改变须先改身份而非靠行动，停滞是潜意识求安全的结果。方法：放大“五年不改变”的反向愿景制造失调；写“我就是那种……的人”身份声明；随机闹钟阻断自动驾驶；给内部敌人命名；用一年/一月/每日透镜过滤目标；把人生游戏化，靠系统而非意志力。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","自我改变","身份认同","习惯系统"]},{"slug":"build-with-andrew-course","title":"吴恩达谈 Vibe Coding：意图优先的零代码构建","summary":"吴恩达课程谈 vibe coding：开发正从写代码转向描述意图，逻辑表达取代算法知识成为门槛。做法：先做粗糙可运行版，按目标、输入、布局、功能、输出五维拆解需求，用自然语言描述现象即可调试；结果有随机性，人变为筛选者。结论：人人可成为构建者，但须持续学习才成真本事。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","vibe coding","吴恩达","AI编程"]},{"slug":"math-happen-over-coffee","title":"数学与社交：咖啡如何转化为定理","summary":"Quanta 报道数学发现的社交属性：突破不靠孤独天才，而诞生于走廊偶遇、共餐与咖啡闲谈。Oberwolfach 研究所限网强制共餐；一杯偶遇咖啡促成 Anosov 流研究，一顿水饺午餐解开七年僵局。Zoom 给不了非正式试探的温度。雷尼所言：数学家是将咖啡转化为定理的装置。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","数学","科学史","社交与合作"]},{"slug":"cc-cheney-1","title":"Claude Code 工作流：Cherny 的并行协作法","summary":"Boris Cherny 的 Claude Code 工作流：并行运行多个实例，团队共用纳入 Git 的 CLAUDE.md，把踩坑经验固化为共享资产；先在 Plan Mode 定计划再自动实现；高频流程封装为指令，Subagents 拆解流水线，MCP 打通工具链。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","工程效率"]},{"slug":"strauss-meme-dotey","title":"施特劳斯模因：双层信息的识别与免疫","summary":"用施特劳斯的双层真理框架剖析知识付费类模因：表层是安抚焦虑的“高贵的谎言”，深层是利用身份认同与沉没成本变现的商业闭环，把结构性困境转化为个人责任。向上靠身份认同阻止觉醒，向下靠社会成本令精英沉默。给出三步识别测试，主张常问“谁在获益”，建立清醒的认知免疫。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","施特劳斯","模因","信息鉴别","知识付费"]},{"slug":"ak-llm2025","title":"Karpathy 年度综述：2025 年 LLM 关键范式","summary":"Karpathy 年度综述：RLVR 以可验证奖励换思考时间；LLM 是锯齿状幽灵心智，不能按生物逻辑审视。Cursor 代表应用编排层，Vibe Coding 让代码廉价可弃。LLM 潜力仅触及一成。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","LLM","Karpathy","RLVR","年度综述"]},{"slug":"jensen-huang-ces2026","title":"黄仁勋 CES 2026：大洗牌与 Agentic AI 蓝图","summary":"黄仁勋 CES 2026 要点：计算从编程软件转向训练软件，AI 进化为会“三思而后行”的 Agentic AI，成为主动的数字员工，程序员转为审核员；DeepSeek R1 证明开源可达前沿，Blueprint 揭示大脑加工具加路由的构建逻辑；多模型协作是终局。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","黄仁勋","Agentic AI","NVIDIA","CES"]},{"slug":"weiss","title":"魏尔斯特拉斯函数：摧毁几何直觉的数学怪物","summary":"1872 年魏尔斯特拉斯构造“处处连续却不可导”的函数，摧毁了“连续必光滑”的几何直觉：放大只暴露更深的锯齿，连续与可导是独立性质。反例迫使数学重构为精确的 ε-δ 体系；这类怪物后来在布朗运动与金融模型中成为基石。数学只承诺一致与可证明，不以安抚直觉为使命。","format":"poster","added":"2026-11-07","tags":["思想与人文","数学","数学分析","直觉与逻辑"]},{"slug":"cc101","title":"Claude Code 入门 101：思维先行的实操手册","summary":"Khrais 的 Claude Code 入门心法：思维先行，Plan Mode 五分钟省数小时调试；CLAUDE.md 限 200 条内，多讲“为什么”；上下文占用超三成即降智，单会话单功能，及时 /clear；Opus 做大脑、Sonnet 做手脚；以脚本建立反馈闭环。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","提示词"]},{"slug":"ai-roadmap-2026","title":"2026 AI 工程师路线图：五个系统级项目","summary":"2026 AI 工程师路线图：薄层套壳无护城河，必被巨头吞噬；胜负手在编排、记忆与本地推理。五个项目：SLM 端侧架构、自愈代码代理、多模态编辑流、本地加密知识图谱、企业级多智能体编排。结论：系统交付者不可替代，选一个项目周末就动手。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","AI工程师","路线图","Agent"]},{"slug":"sama-decline","title":"Sam Altman 衰亡史","summary":"Marcus 论 OpenAI 的衰落：苹果弃独家合作转向 Gemini，DeepSeek 价格战使模型商品化，GPT-5 平庸印证算力边际递减；循环融资与空洞 AGI 承诺透支信任，竞品蚕食市场。结论：魅力无法替代护城河，OpenAI 正沦为 WeWork 式泡沫。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","OpenAI","行业评论"]},{"slug":"cc-cherny-3","title":"Cherny 工作流：从看守者到指挥官","summary":"Cherny 工作流：要做编排并发的指挥官——并发 15 个会话消灭等待；Opus 慢模型换快交付；CLAUDE.md 纳入 Git 作共享记忆；Plan Mode 先谋后动，子代理分工测试，MCP 连接 Slack 等。核心：建立“生成-测试-修复”闭环，质量提升两三倍。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","工程效率"]},{"slug":"read-twice","title":"双重阅读法：初读探索，复读建造","summary":"双重阅读策略：单次阅读带来虚假满足，大脑无法在未知语境中同时探索与建构。方法是把阅读拆成两次任务：初读只扫盲建立语境、克制笔记只做记号；二刷才拆解论证结构、审查逻辑，像建筑师看图纸。如此反而更省时，还能筛选哪些书值得深钻。结论：真正改变人的书几乎都不是只读一遍的。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","阅读方法","学习","认知"]},{"slug":"markdown","title":"Markdown 的崛起：纯文本如何成为世界语","summary":"Anil Dash 论 Markdown 的崛起：它源于写作者手写 HTML 的真实痛点，沿用邮件纯文本习惯近乎无感；无专利开源、社区共建、恰逢博客爆发，加上源码自解释与易编译，成为数字世界的通用基石。结论：互联网基础设施往往源于普通人解决自身痛点的无私分享，而非巨头蓝图。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","Markdown","互联网史","开源"]},{"slug":"dhh-ai-agent","title":"DHH：从结对编程到带领数字团队","summary":"DHH 论 AI Agent：拒绝抢键盘的补全式结对编程，转向结果导向的异步交付；让 AI 掌控终端跑测试、写代码，从辅助工具晋升为受监督的团队成员。2026 年模型质量飞跃，但“AI 写九成代码”是夸大，全自动尚有距离。结论：亲自入场，见证机器思考的历史进程。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","DHH","AI Agent","编程"]},{"slug":"quantum-computing","title":"闭嘴去计算：量子诠释之争与实用主义","summary":"量子力学诠释之争与“闭嘴去计算”的实用主义：叠加态、纠缠等反直觉现象催生哥本哈根、多世界等诠释；爱因斯坦坚持理论须完备实在，费曼等人主张理论有效即足够。历史证明实用转向带来晶体管、激光与量子计算，但默敏警告：把量子力学粉饰得过于平庸，可能让人错失关于世界最深刻的真理。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","量子力学","科学哲学","物理学史"]},{"slug":"software-youtube-moments","title":"软件的 YouTube 时刻：AI 时代的创作平权","summary":"a16z 论“软件的 YouTube 时刻”：AI 把数周开发压缩到数小时，软件从效用工具变为自我表达媒介，像视频一样即时、有趣、可传播。准入证从技术能力变为创意与执行力；软件有抗衰减性，长期积累价值。模仿效应令构建病毒式普及，年轻人借 AI 获得代理权，把命运握在自己手中。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","AI编程","软件","创作平权"]},{"slug":"hn-popularblog-2025","title":"2025 年 Hacker News 热门博客的制胜策略","summary":"Michael Lynch 分析 2025 年 HN 热门博客：个人 IP 胜出，真实人声取代公关通稿；把封闭平台内容深加工到开放网络是高价值策略。案例涵盖中立生态观察、视频转译、逆向叙事、深度调查与交互叙事，爆款常靠坚持重投。秘诀：对共识持有明确而不同的立场。","format":"poster","pages":2,"added":"2026-11-07","tags":["内容创作","博客","个人IP","Hacker News"]},{"slug":"cc-cherny-2","title":"Cherny 工作流续篇：并行、共享记忆与验证闭环","summary":"Claude Code 续篇：并行运行 10–15 个实例消灭等待；Opus 慢思考反而更快；Git 化的 CLAUDE.md 让实例不重蹈覆辙；Plan Mode 先谋后动，子代理分工测试，MCP 连接 Slack 等。核心：建立“生成-测试-修复”闭环，质量提升两三倍。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","工程效率"]},{"slug":"work-on-notes","title":"小平邦彦的数学学习法：抄读、重构与直觉","summary":"菲尔兹奖得主小平邦彦的数学学习法：读懂数学须手脑并用，把证明逐字抄进笔记、标出不懂处、甚至按己见重写整章。逐步验证逻辑不等于理解，真正的理解是对数学真理的本能直觉，如 2+2=4 般自然，达到后证明可被遗忘。数学如钢琴演奏，需每日数小时练习方能内化直觉。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","数学","学习方法","小平邦彦"]},{"slug":"nano-json-style","title":"JSON 提示词工程：用结构化数据控制 AI 图像风格","summary":"fofr.ai 的 JSON 提示词方法论：自然语言会让模型输出概率平均的“大众脸”，JSON 结构把生成变为可控、可复现的工程流程。要点：精确拆解主体特征、用光线与相机参数规训画质、以 Constraints 划定保留与禁止项；还可逆向提取 JSON 并锁定风格批量生成变体。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","AI绘画","提示词工程","JSON","图像生成"]},{"slug":"chendanqing-ai","title":"陈丹青：AI 时代感官与信任的消亡史","summary":"陈丹青论 AI 时代的消亡史：几秒样本即可复刻逝者声线，声音沦为可编辑数据，“眼见为实”失效；沉溺 AI 伴侣造成灵肉分离，真实被复制稀释成消费品，白领面临“无用阶级”危机。AI 渗透如海水漫入泰坦尼克号：起初静默，待察觉时旧的观看与交流方式已消亡。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","陈丹青","AI伦理","信任危机"]},{"slug":"posse","title":"POSSE 策略：自有发布，它处同步","summary":"POSSE 策略（自有发布，它处同步）：以个人网站为唯一信源，副本分发到社交平台，掌握永久链接与数据主权，平台倒闭封号也不受影响；用 Bridgy、IFTTT 实现发布即忘的自动化，以 Webmention 回拉评论形成闭环。不做数字佃农，在自己土地上耕种，让副本去别人领地流浪。","format":"poster","pages":2,"added":"2026-11-07","tags":["内容创作","POSSE","个人网站","内容分发","IndieWeb"]},{"slug":"leerob-coding-2026","title":"Lee Robinson：代码廉价时代的 AI 编程策略","summary":"Lee Robinson 谈 2026 年 AI 编程：代码廉价化，只会实现功能者价值速降，竞争力转向产品品味。策略：拥抱 AI 编码代理，样板与调试外包给 AI，从 Coder 进化为独立闭环的产品工程师；让 AI 讲原理当导师，警惕“懂了”的错觉，不外包思考。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","AI编程","工程师","产品思维"]},{"slug":"ai-talent-density","title":"全球 AI 人才版图：密度东移与集群竞争","summary":"2026 年全球 AI 人才版图：中国 AI 人才密度反超美国，北京、长三角、大湾区三大集群对湾区形成结构性优势，海淀顶级实验室密度超旧金山；新加坡靠人才政策匹敌欧洲，欧洲相对衰落。结论：算力之外，人才规模与软硬协同生态正成为决定性变量。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","AI人才","地缘政治","产业格局"]},{"slug":"ai-writing-everyto","title":"写作优先者：AI 时代最稀缺的能力","summary":"Warnock 论“写作优先者”：AI 使内容成本趋零，世界被平庸文本淹没，写出观点才是稀缺资产。写作是思维的脚手架：厘清逻辑、即时证明判断力、吸引机会的被动社交、保住独特语调、敏捷合成新趋势；对企业是自带流量的品牌资产。独特声音与人际网络是 AI 无法生成的护城河。","format":"poster","pages":2,"added":"2026-11-07","tags":["内容创作","写作","个人品牌","AI时代"]},{"slug":"cc-31days","title":"Claude Code 31 天工作流：九大关键用法","summary":"Claude Code 工作流：AI 是杠杆而非替代者，Plan Mode 规划、Sandbox 定边界。要点：/init 生成项目记忆，! 直执行 Bash，Esc 回滚，@ 引用上下文，ultrathink 深度推理，--resume 持久会话，Subagents 并行扩展。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","工程效率"]},{"slug":"gentle-seduction","title":"温柔的诱惑：跨越奇点的科幻寓言","summary":"Stiegler 科幻《温柔的诱惑》：自然的守护者从止痛纳米胶囊起步，经神经强化、意识联网、远程临场，最终化作纳米星云跨越奇点。奇点不是爆炸，而是无数次“我只想活得更好”的温柔叠加，是忒修斯之船式寓言：替换所有零件后，“我”还存在吗？结局：改变是永恒常量，她既是那座山，也是星空。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","科幻","奇点","忒修斯之船","技术哲学"]},{"slug":"antirez-anti-ai-hype","title":"编程现实主义：antirez 论手动编程的终结","summary":"Redis 作者 antirez 编程现实主义：LLM 已能独立完成中型项目，数周工作缩至数小时，角色从写代码者变为验收者。关键能力是构建问题的心理表征，项目越文本化 AI 效果越好；AI 正如开源运动般技术平权，开源模型紧追闭源。劝告花数周磨合工具，否则将被淘汰，正视失业风险。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","AI编程","antirez","编程"]},{"slug":"ai-pricing","title":"AI 定价策略：五种模式与三条原则","summary":"AI 定价困境：每次调用都烧钱，最忠实用户反成最贵成本中心。五种模式：按量付费透明但预算难测，席位订阅有效率悖论，基础加超额适合高粘性工具，积分制化解心理负担，结果导向受归因难题限制。原则：定价须覆盖真实成本、与价值单位对齐、照顾预算确定性；工程师须有财务思维控成本。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","定价策略","AI产品","商业模式"]},{"slug":"dankoe-next2years","title":"Dan Koe：通才时代与第二次文艺复兴","summary":"Dan Koe 论通才时代：专精是工业时代的骗局，单一技能在 AI 时代自断后路，护城河在多元兴趣的交集与独特观点。路径：打造承载兴趣的载体业务，靠自我教育、自身利益与自给自足的三角获得主权；经营“你即利基”的品牌，建创意博物馆收藏稀缺洞见，把方法论产品化公开迭代获利。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","通才","个人品牌","自我教育"]},{"slug":"skills-at-21century","title":"21 世纪技能：AI 放大专业深度的杠杆","summary":"Levie 论 AI Agent 时代的技能价值：自动化不会消灭技能，而是放大专业深度——领域知识才能定义任务、判断 AI 输出。工程师的价值在系统集成与全局视野，把重复劳动外包给 AI；工具越强，市场对专业度期待越高。AI 降低门槛、抬高天花板，学习者可加速进化。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","职业技能","自动化"]},{"slug":"tolkin-create-as-duty","title":"创造的召唤","summary":"托尔金的“次创造”神学：消费让人灵魂空心化，而人照造物主形象受造，创造即参与神圣秩序。实践上要抵抗虚无、在创造中锻造灵魂、为他人益处施展天赋；借《尼格尔之叶》警惕完美主义，未竟之功在爱中不会落空。结论是勿等“有朝一日”，从当下的小角落怀着崇敬与紧迫感开始创造。","format":"poster","pages":2,"added":"2026-11-07","tags":["思想与人文","托尔金","创造观"]},{"slug":"be-polymath","title":"成为通才：跨领域精通的成长方法论","summary":"成为通才的方法论：过度专业化是思维牢笼，通才应在多个领域精通并跨界融合，深度与广度共生。实践上要保持空杯心态、用微习惯系统替代宏大目标、以体能和聚焦为认知基石；学习从记忆进阶到创造，平台期正是神经重塑的关键，坚持刻意练习直到质变。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","通才","学习方法","刻意练习"]},{"slug":"suck-create","title":"创作的痛苦即意义：拒绝 AI 捷径","summary":"论创作中痛苦的价值：AI 生成内容乍看完美实则逻辑脆弱，依赖无痛捷径会让人失去打磨思想的能力。写作是对大脑的锻炼，卡壳与停滞正是价值所在，用 AI 填补空白等于作弊；AI 摘要只是平均值，亲自阅读才有独特连接。结论：唯有穿越痛苦、坚持原创，才能拒绝平庸。","format":"poster","pages":2,"added":"2026-11-07","tags":["内容创作","写作","AI创作","原创","深度思考"]},{"slug":"terence-tao-erdos728","title":"陶哲轩：AI 驱动的数学证明与高重数论文","summary":"陶哲轩谈 AI 驱动的数学证明：AI 在 Erdős #728 上建立“乒乓式”闭环——澄清模糊定义、给出小常数证明、转 Lean 形式化验证并自动修正错误，再回译为流畅自然语言，最终覆盖全参数场景。更大变革是文本极速重写：论文可按受众生成多版本，标志“高重数”动态论文时代到来。","format":"poster","pages":2,"added":"2026-11-07","tags":["AI","陶哲轩","AI数学","形式化验证","Lean"]},{"slug":"cc-cheney","title":"Cherny 的 Claude Code 工程配置法","summary":"Cherny 的 Claude Code 配置：并行运行多个实例，用 Opus 少纠偏；CLAUDE.md 作团队外脑，Plan Mode 先策后动，Hooks 固化流程，Subagents 专人专事，预设权限白名单。给 Claude 自我验证闭环，质量提升 2–3 倍。","format":"poster","added":"2026-11-07","tags":["工程技术","Claude Code","AI编程","工程效率"]},{"slug":"google-prompts-good-life-2026","title":"Gemini 生活指南：用 AI 落地新年目标","summary":"Google 的 Gemini 生活指南：决心夭折多因执行颗粒度粗糙，Gemini 可充当把愿景拆解为微任务的外部执行系统。九个场景：体能训练表、30 天整理微任务、语言课程测验、膳食与购物清单、支出预算、月度书单、坏习惯替换协议、反向维护计划。以精密系统取代脆弱的意志力。","format":"poster","pages":2,"added":"2026-11-07","tags":["个人发展","Gemini","目标管理","习惯养成","AI"]},{"slug":"x-article-guide","title":"\uD835\uDD4F Articles 官方指南","summary":"X Articles 官方创作指南：从明确写作意图、具体有力的标题与首句钩子入手，按移动端扫读习惯组织段落与视觉节奏，用对话式语气和实证增强可信度；初稿后删减两三成冗余；发布前预告、发布后72小时用推文串引流并互动；最终以软性付费墙将免费流量转化为订阅收益。","format":"poster","pages":2,"added":"2026-11-07","tags":["内容创作","写作","社交媒体"]},{"slug":"ai-100business","title":"智能体工程论：语境决定生产力","summary":"Vasuman 智能体工程论：多数失败源于缺乏上下文工程而非模型不足。要点：跨会话传递历史与政策；目标是人效倍增；单体、并行或协作架构是核心决策；拒绝只展示问题的看板，要强制解决异常；自建智能体是资产而 SaaS 是债务；项目须三个月内进生产。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","AI Agent","上下文工程","架构"]},{"slug":"bank-list-managment","title":"纯文本复式记账十年：Beancount 实践案例","summary":"S. Goel 纯文本复式记账十年：4.5 万行 Beancount、万笔交易，靠 Git 与本地存储守住数据主权。每月仪式（下载、转换、平账）仅 45 分钟；自写脚本适配德国银行，凭证 PDF 直链账本，年度归档保持主文件轻量。纯文本低熵耐久，是最经得起时间的个人数据库。","format":"poster","pages":2,"added":"2026-11-07","tags":["工程技术","复式记账","Beancount","纯文本","数据主权"]},{"slug":"venture-is-dead-again","title":"资本规模膨胀与不确定性背离：风险投资为何再次死亡","summary":"头部风投基金规模急剧膨胀，导致合伙人人均管理资产激增，迫使其在推高估值、搭便车或转向成熟期之间妥协，背离了通过小额多注与阶段注资承担奈特不确定性的本质，重演上世纪八十年代向并购转型与回报崩塌的历史。","format":"magazine","added":"2026-11-16","originalDate":"2026-11-11","tags":["其他","风险投资","奈特不确定性","基金规模"],"studioId":"cfa33c43e91a4438f09e43929530ac5658c7304a1202a51e389193aa97f72582"},{"slug":"why-writing-correct-software-is-hard","title":"从计算复杂性看软件正确性的固有代价与证明边界","summary":"本文从可计算性与计算复杂性理论出发，系统论证软件正确性并非工具选型问题，而是受制于如物理定律般的计算法则。无论是全函数语言、模块化分解还是高级类型系统，都无法消除状态爆炸与验证难度的指数膨胀。","format":"magazine","added":"2026-11-13","originalDate":"2016-07-23","tags":["工程技术","形式化验证","计算复杂性","程序正确性"],"studioId":"edaf4b834521fc7006313c4f4bdcf7069b369afc16b89a2f36ed5494c1d48cfa"},{"slug":"from-inference-to-execution","title":"从推理走向执行：智能体时代的算力重构与商业博弈","summary":"本文指出AI发展重心正从模型训练与GPU推理转向以CPU和状态调度为主的任务执行。应用组装层掌握动态路由与成本组合权，正将底层基础设施变为可替换的供应商，拥有最多GPU将不再等同于捕获最大商业价值。","format":"magazine","added":"2026-11-10","originalDate":"2026-10-17","tags":["AI","智能体","算力经济","基础设施"],"studioId":"d9e57afd8e73eb38f6f2c9d558c4cd7185bada09aeb86fe41306b75062688da0"},{"slug":"long-horizon-agents-and-durable-execution","title":"长周期智能体与持久化执行的企业级架构实践","summary":"文章探讨长周期智能体在企业复杂流程中的落地范式，提出结合持久化执行运行时解决长达数周等待与故障恢复，并强调持久化不等于正确性，必须在框架层通过实体工作流、幂等性、有效期待校验与业务规则版本化应对现实挑战。","format":"magazine","added":"2026-11-10","originalDate":"2026-11-10","tags":["工程技术","长周期智能体","持久化执行","软件架构"],"studioId":"530fc0a7c6a80c2747f9f4f8e023a4065cdb888474c1b65cc390358e90648c6e"},{"slug":"teaching-ai-to-build-scientific-models","title":"超越数据拟合：让AI通过模型分布探寻科学洞察","summary":"科学建模的目标是洞察而非单纯拟合。面对参数与结构的欠定性，AI不应仅提供单一最优解，而应搜索并呈现与数据相符的模型分布，通过揭示存活模型的共有特征及失败替代方案，指导后续实验并加深科学理解。","format":"magazine","added":"2026-11-10","originalDate":"2026-11-06","tags":["AI","AI科学发现","科学建模","模拟推断"],"studioId":"e0dfbcdf3b49b9ea49643be81d7eeb3a2e8756dcdf8b5e0535ea68c57dd5a9c0"},{"slug":"the-components-of-agent-memory","title":"智能体记忆组件与离线梦境整理机制","summary":"Anthropic 区分智能体的短期工作记忆和跨会话长期记忆，并讨论利用空闲算力回顾经历、修正旧记录和构建知识库的做法。","format":"magazine","added":"2026-11-10","originalDate":"2026-11-06","tags":["AI","智能体记忆","离线计算","维基知识库"],"studioId":"5c4b3b6307c61f787dfc61141455f9cbdb756d9c33c8b4d4f7e6e476a7f38b41"},{"slug":"uchicago-writing-center-and-generative-ai","title":"芝加哥大学如何为独立写作留出空间","summary":"芝加哥大学成立写作中心，希望学生在起草、讨论和修改中形成自己的想法。中心负责管理一门强调独立阅读和写作的本科核心课，课程安排同伴互评，计划从2027年秋季起面向所有新入学本科生设为必修。中心也准备开设课程和实验空间，让师生探索人工智能与写作的关系。","format":"magazine","added":"2026-11-10","originalDate":"2026-10-30","tags":["思想与人文","写作教学","通识教育","同伴互评"],"studioId":"8c01517a9142debaed93df592e212196437c9f722dc52b125af0fb59ed887f22"},{"slug":"why-material-design-failed","title":"Material Design全线溃败的根源复盘","summary":"本文系统复盘了Material Design历经十二年的溃败历程，指出其失败根源在于把设计系统当作自嗨形式而非工程基础设施契约，因频繁破坏性重构与晋升驱动开发导致生态背离，最终沦为缺乏约束力的局域网产品。","format":"magazine","added":"2026-11-10","originalDate":"2026-10-13","tags":["工程技术","设计系统","人机交互","安卓生态"],"studioId":"9e41a207a07db6bda33680bc548a25ef95df480d6f94b8a8212c303289450d93"},{"slug":"a-return-to-code","title":"氛围编程重塑软件开发与纯软件投资范式终结","summary":"AI编程智能体正将软件开发门槛降至零摩擦，催生极端定制的个人应用与单人规模化公司，同时颠覆传统图形界面与应用商店生态，使纯软件失去风投壁垒，驱动软件创造重心从工程实现转向人类愿景与审美把控。","format":"magazine","added":"2026-11-06","originalDate":"2026-04-29","tags":["其他","氛围编程","AI编程智能体","软件工程"],"studioId":"240a24f61a5cfd93c9c2127cd4c723b29f532b8e6c32fb733619bc81d31cd54f"},{"slug":"ai-industrial-revolution","title":"AI工业革命：从软件工厂走向硬件与监管重构","summary":"探讨人工智能驱动下的生产力跃迁，工程师正从代码编写者转为软件工厂架构师与结果验证者，算力杠杆不仅重塑超音速客机与脑机接口等物理工程研发，更开始颠覆审批迟滞的监管制度与医疗体系。","format":"magazine","added":"2026-11-06","originalDate":"2026-06-02","tags":["工程技术","人工智能","软件工程","硬件制造"],"studioId":"0d410ddbe177b1b4d46ba3d48936b950f71895860b68a92c6ac68a14150293e0"},{"slug":"hodge-conjecture-and-mathematical-value","title":"霍奇猜想的研究现状与人工智能时代的数学探索价值","summary":"文章梳理了霍奇猜想在代数几何与拓扑学之间的核心纽带作用，回顾了从列夫谢茨定理到马克曼最新证明的发展脉络，并深刻反思在人工智能大举介入数学证明的当下，数学探索的真正价值在于人类交流启发而非孤立结论。","format":"magazine","added":"2026-11-06","originalDate":"2026-09-12","tags":["思想与人文","霍奇猜想","代数几何","数学哲学"],"studioId":"c83d06fe6a9e077bab3eab5d67257f7bada066ba306cb47d3e343da3749e66bb"},{"slug":"how-universities-should-prepare-founders","title":"大学培养创始人的核心之道是留出闲暇并鼓励自发实践","summary":"大学无需设立创业课程或商赛，而应专注硬核学科教学，通过同辈榜样建立可能感，并给予充裕闲暇让学生自主折腾业余项目。真正的颠覆性产品与创始团队，往往在不受行政干预的野蛮探索中自然涌现。","format":"magazine","added":"2026-11-06","originalDate":"2026-11-06","tags":["其他","创业教育","高等教育","创新机制"],"studioId":"925385dbe6749253ea1b887f5b14693db53c833b01e7119b295cf6c3046ac34a"},{"slug":"motorcycle-for-the-mind","title":"心智摩托：人工智能重构编程范式与人类能动性","summary":"自然语言正在取代传统代码成为新交互界面，而模型训练与系统调优构成了新的底层编程。在工具泛滥与平庸淘汰的时代，懂底层逻辑的工程师获得极高杠杆，拥有极致能动性的人类将把AI作为心智载具去探索全新未知。","format":"magazine","added":"2026-11-06","originalDate":"2026-02-20","tags":["思想与人文","人工智能","软件工程","创业哲学"],"studioId":"27ddc08fc8d249ca458501bcfab8248a03f1cdc9856adb802ffade1d522f2f5a"},{"slug":"the-brand-age","title":"从瑞士手表的转型看品牌与设计的根本冲突","summary":"本文通过瑞士机械表转型奢侈品的历程，揭示技术抹平实质差异后品牌的崛起逻辑，指出品牌追求独特性与优秀设计追求客观最优解之间的根本冲突，并警示远离品牌操弄、追随真实问题方能进入黄金时代。","format":"magazine","added":"2026-11-06","originalDate":"2026-11-06","tags":["思想与人文","商业史","品牌战略","工业设计"],"studioId":"93909262851d1f7a1d3c862ba3f8208542dde08f2ff5f2d8c3cd7bbec64a307d"},{"slug":"austin-lau-on-building-a-growth-engine","title":"奥斯汀\xb7刘谈如何搭建增长体系","summary":"奥斯汀\xb7刘建议，增长团队在前九十天先把业务目标转成可衡量的任务，再安排少数重点实验。早期可以用小型活动检验受众和信息是否匹配，同时投入需要时间积累的搜索优化、推荐和合作渠道。等产品转化、效果衡量、创意和工程支持到位后，再根据现有需求和目标人群选择付费渠道。","format":"magazine","added":"2026-11-05","originalDate":"2024-07-10","tags":["其他","增长策略","生命周期营销","增长实验"],"studioId":"40cc10b150c14ca0eb002905838eb2f9ededefca5650dbd22db04e760f2e71fb"},{"slug":"interstellar-medium-dynamic-flux-map","title":"银河系星际介质三维新图谱颠覆传统宁静平衡模型","summary":"天体物理学家结合盖亚望远镜三维尘埃图与紫外辐射数据，发现四成以上星际介质处于理论预测之外的不稳定过渡态，表明星际空间并非静止平衡的背景，其持续的动态搅拌循环有望解开恒星形成效率低下的长期谜题。","format":"magazine","added":"2026-11-05","originalDate":"2026-10-30","tags":["工程技术","星际介质","盖亚望远镜","恒星形成"],"studioId":"5d2ccf4f6d4717626467da3c77f9d6ae36ad7fa71074c39592f40c06da8761d4"},{"slug":"ai-impact-mathematics-reputation-crisis","title":"AI冲击下的数学危机与学术信誉重塑之道","summary":"面对AI批量攻破数学猜想引发的第四次数学危机，作者剖析了数学界脱离现实、信任外包与评价异化的沉疴，指出以期刊为核心的信誉体系必然崩盘，呼吁数学研究摆脱解题内卷，回归经验源头、现实关怀与内心审美独立。","format":"magazine","added":"2026-11-04","originalDate":"2026-11-04","tags":["思想与人文","数学哲学","人工智能","学术评价"],"studioId":"431cccd75e76feb413d6c94b458d62f5b36a2858235b7df25f9d520e918ea9a2"},{"slug":"disadvantages-designating-mathematicians-ai-releases","title":"AI数学成果发布中指定数学家的弊端与治理建议","summary":"数学与人工智能咨询组指出，AI企业在发布数学成果时指定特定学者背书与解读，会造成不平等准入、削弱学科自主权并扭曲激励机制，呼吁转向透明披露、形式化验证及由独立机构资助的开放社区协同模式。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-26","tags":["思想与人文","人工智能与数学","学术共同体","科研伦理"],"studioId":"791657baf49648ff582ea6f9e24aaf64849994c9e07973c43ce82aae2096397a"},{"slug":"earth-sized-telescope-black-hole-shadow","title":"以地球尺度望远镜捕捉黑洞阴影与未来动态成像探索","summary":"访谈阐释了事件视界望远镜如何借助甚长基线干涉技术，将全球射电阵列连为地球大小的虚拟透镜捕捉黑洞阴影，从而验证广义相对论，并勾勒出未来通过增设基站拍摄吸积流动态电影以测定黑洞自旋的技术路径。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-29","tags":["工程技术","事件视界望远镜","黑洞","甚长基线干涉"],"studioId":"ff081e3be9ff0aa41be4e0b29fdd307b2c670d6fa8ccf137e4bdea5f572dbc84"},{"slug":"how-spiders-spin-silk-dope","title":"解析蜘蛛丝从液态原浆到超韧纤维的相变机制","summary":"研究团队通过核磁共振与分子模拟首次揭示，黑寡妇蜘蛛利用磷酸盐触发液液相分离，通过精氨酸与酪氨酸的弱相互作用形成凝聚体分子贴纸，将无序原浆蛋白高效预组装为超强韧固态蛛丝。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-29","tags":["工程技术","蛛丝蛋白","生物材料","液液相分离"],"studioId":"5a4caa532e0b949fd5ca0dcb6770276f51e903daece48e3c5efa397471d4e94d"},{"slug":"math-education-public-goods-problem","title":"AI冲击下的数学教育与心智训练公共品困境","summary":"面对AI对复杂推理的替代，文章指出数学教育的真正危机是心智训练生态的萎缩。当自动化削弱了初级岗位的智力锻炼机会，维持人类深度理解与批判思维已演变为必须由公共资源兜底的公共品问题。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-30","tags":["思想与人文","人工智能","数学教育","公共品困境"],"studioId":"0b519bac3b86bd3e126f033ed003da1e36b3bc434836db92ca97822fee5698db"},{"slug":"mathematics-is-a-subject-for-the-young","title":"机器证明冲击下的数学理解价值与学术生态重构","summary":"面对算力驱动的机器证明浪潮，数学界正从证明稀缺步入证明充裕时代，核心价值转向对本质规律的人类理解；学界亟需抵御巨头数据掠夺，建设开源基础设施，并重构基于思想深度而非抢先首发的新评价机制。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-22","tags":["思想与人文","人工智能","数学研究","学术评价"],"studioId":"323bfd1052c6ee7d550163885645524a5136855ff65f03cc3bfcd94cc280ab77"},{"slug":"tenth-discriminant-siegel-zeroes-ai-challenge","title":"利用第十判别式上界排除西格尔零点的AI实验挑战","summary":"陶哲轩提出一项协作型AI数学挑战，呼吁利用AI工具从排除西格尔零点的最新证明中推导出虚二次域第十判别式的显式有效上界，以此横向比较不同证明框架的强度并探索类数问题的新思路。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-20","tags":["工程技术","西格尔零点","第十判别式","数论"],"studioId":"3972f6d552a25e8a24f538b8eab2fdcf18ee86f52e5bb12b61f62d58ce5ad8ea"},{"slug":"unstable-interstellar-medium-3d-map","title":"银河系星际介质三维新图颠覆经典静态平衡模型","summary":"天文学家结合盖亚测距与紫外辐射数据绘制出三维星际介质图谱，发现超过四成气体处于经典理论禁止的不稳定相，彻底动摇了银河系介质处于静态压力平衡的旧假设，为解开恒星形成缓慢之谜提供了全新线索。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-30","tags":["工程技术","星际介质","盖亚望远镜","天体物理"],"studioId":"65daea81cc7924d7e63e7af532c830e9ac05d1a99cd5c96e06cc5d4757e1ce20"},{"slug":"voting-paradox-klein-bottle","title":"孔多塞投票悖论的拓扑学本质与克莱因瓶模型","summary":"数学家利用拓扑学证明了孔多塞投票悖论在几何上等价于克莱因瓶，揭示了个体理性的偏好在聚合时必然出现全局非定向性循环，表明集体决策的内在矛盾并非规则缺陷而是数学拓扑上的必然性。","format":"magazine","added":"2026-11-04","originalDate":"2026-10-26","tags":["思想与人文","投票悖论","拓扑学","克莱因瓶"],"studioId":"a582f9056622693fe6638443f74bd9d2850e6eff81d52069df74a96ec15812cf"},{"slug":"egoless-mathematics-in-ai-era","title":"人工智能时代无我数学的哲学反思与价值重塑","summary":"面对AI对数学研究带来的冲击，文章从柏拉图主义视角倡导无我数学理念，主张数学价值源于客观真理的理解而非个人成就归属，呼吁学者超越绩效与比较焦虑，以非功利的纯粹追求重塑智识生活的深层意义。","format":"magazine","added":"2026-11-03","originalDate":"2026-11-03","tags":["思想与人文","数学哲学","人工智能","认知价值"],"studioId":"87efdc6758c71f2857dd55c913a2df97bbad7b08cbcd9de1c797c000baa152ec"},{"slug":"mit-open-courses-for-a-quantum-career","title":"一名工程师如何用开放课程转向量子研究","summary":"奥马尔\xb7阿尔谢赫里从工业工程转入纳米技术，再攻读量子物理方向的博士。他用麻省理工学院的开放课程补习材料科学、电子学和量子力学。据他自述，为修读一门量子光子学与电子学课程，他在线学习了约三百小时。导师也看重他的工程经验，他由此把研究兴趣转向实现量子物理现象所需的设备。","format":"magazine","added":"2026-11-03","originalDate":"2026-04-14","tags":["个人发展","开放教育","自主学习","量子物理"],"studioId":"de9085c6d8e2363b344288eafa1d633cd9749f9b3ecfa18906321c65cfed1b0b"},{"slug":"rethinking-mathematics-in-the-ai-era-2","title":"AI时代数学价值重排与从解题证明转向框架阐释","summary":"当大模型将定理证明成本大幅压低，传统以解题为核心的智力稀缺性神话被打破。数学研究的价值重心正不可逆地转向源于现实的新框架构建，以及对海量机器证明的深度消化与概念阐释。","format":"magazine","added":"2026-11-03","originalDate":"2026-11-03","tags":["思想与人文","数学研究","学术评价","知识传播"],"studioId":"54c8531f69bf613a3ba95b661b22f45b32e7a4931d53cb9e0658b6a6e6469fb9"},{"slug":"rethinking-mathematics-in-the-ai-era","title":"定理经济瓦解：AI时代的数学研究范式与制度重塑","summary":"面对AI破解猜想引发的学界焦虑，数学家卡莱加里指出数学核心在于结构理解而非孤立证明。学术界应改革招聘、期刊和研究生培养机制，促使学者利用AI打破狭隘分工，转向更有野心的跨领域探索与宏观构想。","format":"magazine","added":"2026-11-03","originalDate":"2026-11-02","tags":["思想与人文","人工智能","数学研究","学术评价"],"studioId":"01b899d94758f9736d96cf9b7fd92774b71e9abd648964b151cb1f78b5a52b68"},{"slug":"steve-jobs-smithsonian-interview-1995","title":"史密森尼乔布斯访谈：技术人文融合与制度竞争反思","summary":"乔布斯回顾个人成长与创业历程，阐释计算机作为赋能工具的本质，反对将技术视作教育万灵药，主张推行教育券与市场竞争机制，同时深刻论述顶尖人才密度、技术人文融合以及互联网重构商业分销的时代趋势。","format":"magazine","added":"2026-10-31","originalDate":"2026-10-31","tags":["思想与人文","技术哲学","教育改革","人本主义"],"studioId":"ec216b1801dd60bebb489f6d9ebb35bd4df9b0fd649b5cc4bf055921eba75df7"},{"slug":"the-year-ai-ate-math","title":"AI攻破纯数学防线引发的意义危机与认知重构","summary":"面对AI快速攻破数百个数学难题的冲击，数学界在知晓答案与理解本质之间产生了范式分流，促使人们反思数学究竟是独立于人类的客观科学发现，还是依托人类心智体验、创造力与情感连接而存在的精神探索。","format":"magazine","added":"2026-10-25","originalDate":"2026-10-25","tags":["思想与人文","人工智能","纯数学","科学哲学"],"studioId":"67ee8eca751306f06c27386d97d17865f9be328e0d683bf94cfbfa3c2af5a1a9"},{"slug":"ai-proves-quasi-riemann-hypothesis","title":"AI证明拟黎曼猜想打破百年僵局引发数论研究震动","summary":"据 Quanta 报道，AI 给出了拟黎曼猜想的证明。文章介绍独立核验与形式化验证的进展，并讨论这一成果对数论研究和数学家工作的影响。","format":"magazine","added":"2026-10-20","originalDate":"2026-10-19","tags":["AI","数论","黎曼猜想","形式化验证"],"studioId":"82934f644ebcd78490dc652cb587ea97e0e00aaff27e5f702aaa7cd52fc5846f"},{"slug":"after-math-beyond-problem-solving","title":"数学超越解题：AI时代的证明、理解与学科本质","summary":"针对OpenAI给出纳维斯托克斯方程解的热议，文章指出数学不仅是解题游戏。形式化工具虽能验证逻辑正确性，但人类可理解的洞见与概念构建才是数学的灵魂，数学界应重新审视被自动化指标绑架的定理经济。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-13","tags":["思想与人文","数学哲学","形式化证明","机器理解"],"studioId":"891217df8969bfa202a8c3054d50ad7732c8f726a8b44d66a6a1512d7bcadd39"},{"slug":"ai-breaks-the-theorem-proxy","title":"定理不再稀缺：AI冲击下的数学评价与理解危机","summary":"数学长期将定理证明作为人类深刻理解的代理指标，但AI以极低成本批量合成跨领域证明打破了该机制；数学界亟需重构激励体系，将评价核心从证明结论本身转向洞见阐释、概念创造与群体理解。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-14","tags":["思想与人文","数学研究","人工智能","科研评价"],"studioId":"fef692cd622117c00aa88291e125a45ba8ef14c3d40cd06afa09a49e2f99f3d9"},{"slug":"becoming-a-benchmark","title":"当研究沦为AI基准：从程序语言到数学的突围之道","summary":"面对AI将专业研究吞噬为评测基准的冲击，形式化验证学者分享了从焦虑到重构价值的应对经历，提出数学界应直面公众构建公关防线，坚持过程价值与参与式协同，守护与跑分机制截然不同的学科本质。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-17","tags":["思想与人文","人工智能","形式化验证","数学研究"],"studioId":"c84b715da069396e80472b8c2c14e77e081842ce8ecf14683e76cb577f8875db"},{"slug":"cognitive-sanctuaries-academic-manifesto","title":"认知避难所：AI时代重构博士培养与学术评价体系","summary":"面对生成式AI轻易制造论文与转移技术债务的困境，作者呼吁在系所层面建立认知避难所，通过革新博士考核、重塑教师奖励并重聚学术共同体，将科研重心从产出指标重新校准回对理解过程与人类思维磨砺的尊重。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-28","tags":["思想与人文","学术评价","博士教育","人工智能"],"studioId":"d768d0f5562d49bc3a2b853f475deae08b337cc97caa103d22102ccd206b6128"},{"slug":"erdos-problems-human-mathematics","title":"埃尔德什问题网改版与AI时代人类数学的价值坚守","summary":"面对AI生成证明涌入与功利化抢发风气，埃尔德什问题网站宣布冻结解题评论、隐去已解决状态并取消证明归属表述，通过去游戏化机制引导社区重回人类理解、数学协作与高质量阐释的本质。","format":"magazine","added":"2026-10-19","originalDate":"2026-10-06","tags":["思想与人文","人工智能与数学","科学共同体","学术治理"],"studioId":"f326ca9ef1dd7a62bf3be8b8f3fca78e65367c16bb3b91c22182c4ec1e70d110"},{"slug":"fast-math-slow-math","title":"快慢数学：AI时代数学家的科研范式重构与理解底线","summary":"文章借慢食运动类比，探讨大模型引发的数学界焦虑，提出融合沉思理解的慢数学与技术驱动的快数学两套范式，倡导设立共同体规范，守住工作速度不超前于理解深度的核心底线，维系数学作为人类认知文明的本质。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-16","tags":["思想与人文","数学研究","人工智能","学术评价"],"studioId":"5aee6061764e57f0e8043e138fbf39ea942aad0c4f63c3545875335f4573c599"},{"slug":"golden-or-dark-age-for-mathematics","title":"大模型时代数学研究的黄金时代与黑暗时代之抉择","summary":"探讨大模型形式化证明对数学与科学的深远冲击，指出证明自动化若缺乏人类理解将导致知识异化与学术垄断，呼吁构建公共科研计算基础设施，将研究重心转向构建新理论概念的数学化创造。","format":"magazine","added":"2026-10-19","originalDate":"2026-10-18","tags":["思想与人文","人工智能","数学研究","形式化证明"],"studioId":"cbf802f15ec2b1f6372ea36819d7c7218e79bf8385d1c06d00db258b12b8de3a"},{"slug":"llms-as-cultural-technologies-in-math","title":"大模型作为文化技术与数学理解的集体遗产","summary":"文章主张将大语言模型视为凝聚人类知识的文化技术而非孤立的人工智能实体，指出模型在数学证明中的突破本质上是人类知识凸包内的重组与显影，数学家应将此类成果视为共同体遗产并坚守以理解本质为核心的科学追求。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-14","tags":["思想与人文","大语言模型","数学哲学","文化技术"],"studioId":"f4e05b312de347f52a157889aab47c5a75d2d61ce51550aaffc47fd9b89de2ca"},{"slug":"mathematical-illustration-beyond-proof","title":"超越形式证明：数学插图的严谨性构建与认知探索价值","summary":"随着人工智能打破定理证明的稀缺性，数学插图展现出超越形式证明的探索价值；它不仅是辅助阐释的媒介，更是通过制作中思考与严谨可供性检验推动数学发现的研究方法，重塑了以社群理解为核心的人类数学实践。","format":"magazine","added":"2026-10-19","originalDate":"2026-10-12","tags":["思想与人文","数学哲学","数学插图","人工智能"],"studioId":"6438c7c79c63848da1efcf5c200fdbf05c9b5cd6901031c9f81a36914c7bcfd7"},{"slug":"non-sofic-groups-and-ai-credit","title":"非索菲克群与人工智能时代的学术信用危机","summary":"数学家安德烈亚斯\xb7托姆通过OpenAI证明非索菲克群引发的学术争议，揭示大模型对用户研究数据的潜在吸纳与学术归属困境，呼吁将人工智能视为受严格监管的公共基础设施，重塑人类对数学理解的核心价值。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-12","tags":["思想与人文","人工智能伦理","学术信用","几何群论"],"studioId":"86b9f0aa2272adfd4008de38837bc05d5c1f6a3a627c8d31cc3a9bafa0155c7f"},{"slug":"technical-debt-of-ai-generated-mathematics","title":"AI生成数学带来的技术债与理解困境","summary":"数学研究的真谛在于人类理解而非单纯答案，AI生成繁冗晦涩的证明虽有正确结论，却把沉重的消化成本转嫁给学术界，形成了危害长远发展的技术债，研究者必须对成果的解释与沟通承担起社会责任。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-15","tags":["思想与人文","人工智能","数学研究","技术债"],"studioId":"ed12c1c67c1fd3ce4bac2528f0ff70431ebdf0f13d9b96fc60ccafdda19ae566"},{"slug":"we-need-more-mathematicians","title":"面对AI前沿重大突破人类社会为何需要更多数学家","summary":"面对人工智能超速产出的突破性科学构想，人类不能因无法跟上而放弃理解责任。为了在受控核聚变等重大技术决策中审验数理模型并捍卫人类自主性，社会不仅不应缩减科研人员，反而亟需建立庞大的数学智力储备库。","format":"magazine","added":"2026-10-19","originalDate":"2026-09-25","tags":["思想与人文","人工智能","数学研究","科学理解"],"studioId":"d80be04da3a7d06b8244d1401bc22b9212297cb55872fdc3d3b2e454e3abf5e4"},{"slug":"why-are-we-even-doing-all-this","title":"当AI将科学探索异化为无人阅读的巴别图书馆","summary":"本文以辛辣反讽的笔调借博尔赫斯的巴别图书馆隐喻，批判了前沿AI批量生成论文所加剧的学术异化。作者指出，科学的核心在于人类对真理的理解与探索乐趣，警惕将好奇心与理解力外包给商业模型而导致的科研虚无。","format":"magazine","added":"2026-10-19","originalDate":"2026-10-16","tags":["思想与人文","人工智能","科学哲学","学术异化"],"studioId":"032517512db6b5b86f58ef0eed0e00f34b3d23f1dd2dc5e5de4a7ed84bb70b26"},{"slug":"science-of-ai-benchmarks","title":"解构大模型跑分困境：让AI基准测试重归科学测量","summary":"计算机科学家莫里茨\xb7哈特指出当前大模型基准测试面临过度刷榜与数据污染危机，主张绝对分数不可信但相对排序仍具价值，提议通过统一的高原训练协议拉平筹备差异，使AI评估从无序博弈回归可靠的经验科学。","format":"magazine","added":"2026-10-18","originalDate":"2026-10-16","tags":["AI","基准测试","大模型评估","数据污染"],"studioId":"8953c37ed9c094ea42914a5b0b0f33c48ea98240c7602d430042e3069a92a612"},{"slug":"lean-theorem-prover-reliability-and-ai","title":"Lean定理证明器的可靠性隐忧与AI时代的数学信任","summary":"著名数学家黑尔斯剖析了自动形式化普及下Lean证明器的可靠性挑战，揭示了其内核漏洞历史与类型论未决难题，并警示过度依赖AI代码审计可能埋下深层安全隐患，呼吁人类学者重视底层数学验证与元理论研究。","format":"magazine","added":"2026-10-14","originalDate":"2026-10-10","tags":["工程技术","定理证明器","形式化数学","类型论"],"studioId":"be2b69a19c73766bea906a6ea9cc3a76d4776d4d44d4b04e1f9a2598b2c4c6b1"},{"slug":"what-godels-incompleteness-theorems-truly-mean","title":"哥德尔不完备定理的真正含义与现代启示","summary":"文章汇聚逻辑学家、哲学家与物理学家的多元视角，围绕连续统假设、逻辑表达力权衡以及时空离散化假说，重新审视哥德尔不完备定理的内涵，揭示出数学真理并非封闭系统，而是需要直觉与持续创新的开放过程。","format":"magazine","added":"2026-10-14","originalDate":"2026-05-18","tags":["思想与人文","哥德尔不完备定理","数学哲学","连续统假设"],"studioId":"8b63f820655913505b58a712328326c0891f005c0fb7767b85d06f5c88371eb7"},{"slug":"ways-of-seeing-chapter-one","title":"机械复制时代艺术神话的阶级祛魅与观看之道","summary":"本书第一章揭示了机械复制技术对传统艺术唯一性与权威的解构，批判了统治阶层与学院派通过形式主义对历史和原作价值的神秘化，主张将图像转化为大众理解历史与经验的平民语言。","format":"magazine","added":"2026-10-12","originalDate":"2026-10-12","tags":["思想与人文","视觉文化","机械复制","艺术史批评"],"studioId":"3a6a879de388bcfb02de22f714b046de60c938866a975d3f9377e55f39be7b94"},{"slug":"blog-post-as-social-search-query","title":"博客即社交搜索查询：以深度写作筛选同道并重塑自我","summary":"文章颠覆了追求大众通俗的传统写作观，提出公开博文实质上是定位同频者的社交搜索查询。通过保留极其小众的特异性细节，创作者能精准过滤泛化受众并吸引优质思考者，进而借助网络层级重构自身智识环境与主体性。","format":"magazine","added":"2026-10-10","originalDate":"2022-10-06","tags":["内容创作","公开写作","博客","智识社区"],"studioId":"113ced9c35aef705683f5797612887c2b91d3c042767c83ad5a1a9b5fba2f3aa"},{"slug":"blogging-as-social-search","title":"把博客当作寻找同好的搜索查询","summary":"亨里克\xb7卡尔松把博客文章当作寻找同好的搜索查询。保留具体的例子、冷门引用和个人趣味，能让原本互不相识的读者认出彼此关心的问题。文章经共同关注的人传开，找到的读者又会寄来资料、工具和新观察。卡尔松认为，公开写作由此可以改变自己与谁交流，进而改变接下来会读到什么、追问什么。","format":"magazine","added":"2026-10-10","originalDate":"2022-10-06","tags":["内容创作","公开写作","博客","信息传播"],"studioId":"d7e1263bf2a8876d72a86e40381e71282c377210357e61b2fbea69b15d00a075"},{"slug":"declaration-on-math-and-ai","title":"菲尔兹奖得主联合声明警惕AI解题指标异化数学探索","summary":"二十余位菲尔兹奖得主联名指出，AI企业将攻克难题作为基准测试的做法正在异化数学研究，解题只是增进概念理解的代理工具，盲目追求真伪判定的大规模生产将破坏人类智力传承并冲击整个科学共同体。","format":"magazine","added":"2026-10-10","originalDate":"2026-09-11","tags":["思想与人文","人工智能","数学哲学","莱顿宣言"],"studioId":"ed3fc47ac9c0da2513e22949c434bb6f9fc28d58d1c60286b76d6c5a1cbc152f"},{"slug":"future-of-pure-math-in-ai-age","title":"计算不可约性视角下AI时代纯数学研究的未来","summary":"面对AI取代数学家的论调，沃尔夫勒姆指出纯数学核心是人类构建概念叙事与设定研究目标，而非机械推导。AI与计算虽能加速检索验证，但从计算不可约宇宙中提炼可理解结构与审美价值仍完全依赖人类思维。","format":"magazine","added":"2026-10-10","originalDate":"2026-09-28","tags":["思想与人文","纯数学","人工智能","计算不可约性"],"studioId":"948499421beebb662c9675bb658cd7bcd9aebc8b913d359b413814000cc63eb3"},{"slug":"ai-and-future-of-mathematics","title":"机器证明冲击下纯数学的理解危机与范式重构","summary":"Quanta 探讨 AI 生成证明对纯数学的冲击。受访者区分可验证的证明与理解证明的过程，并讨论定理解题在学术评价中的地位以及开放交流受到的影响。","format":"magazine","added":"2026-10-08","originalDate":"2026-10-05","tags":["思想与人文","人工智能","数学哲学","学术生态"],"studioId":"5f7688d3f36b6fedf4916ba85be574dcdbf19fda8eefd4fa1e88a859ce48b899"},{"slug":"claude-shaped-science","title":"从阻抗匹配到大模型特质科学的人机协同新范式","summary":"文章剖析了科学家与大模型协作时的阻抗匹配问题，提出依托开源工具BootLoops寻找适配大模型特质的跨学科计算问题，并由领域专家主导科学品味与假设甄别，以人机协同填补不同学科间的知识凸包。","format":"magazine","added":"2026-10-02","originalDate":"2026-10-01","tags":["AI","AI科学发现","人机协同","跨学科计算"],"studioId":"a9dc271390762537c5d2bb793442b3e28819d62a0a1481f51bf411fe33a106d9"},{"slug":"elevating-motivated-explanations-in-math","title":"机器证明时代数学理解的重塑与动机阐释的学术认可","summary":"面对人工智能生成证明对传统数学评价体系的冲击，数学界亟需将动机阐释确立为与形式证明并重的学术成果，通过设立开放阐释问题与改革评价机制，使数学研究真正回归推动人类心智理解的根本目标。","format":"magazine","added":"2026-09-24","originalDate":"2026-09-19","tags":["思想与人文","数学哲学","动机阐释","人工智能"],"studioId":"3c9a32852da09abe958802b21a8e5bf4095227030051afb861cc6c1df61caf5c"},{"slug":"entrepreneurship-in-the-age-of-ai","title":"AI时代的四条创业建议","summary":"AI降低了市场调研、产品开发和试验的成本。MIT斯隆的比尔\xb7奥莱特和珍妮\xb7拉里奥斯\xb7柏林提醒，试验做得再快，也要看有没有客户愿意付费、业务能否盈利、渠道能否触达并留住客户。他们建议把AI用在分析和验证上，由创业者决定要问什么、判断结果并建立客户信任。","format":"magazine","added":"2026-09-24","originalDate":"2026-08-24","tags":["其他","AI创业","客户开发","销售渠道"],"studioId":"c3ca8d8228c09e84051d79b2638e1a4487461adde8fb85b2ba7cb41b2c473232"},{"slug":"gowers-thoughts-on-leiden-declaration","title":"高尔斯评莱顿宣言与AI时代数学文化重塑","summary":"高尔斯审视莱顿宣言指出，AI将打破成果所有权与署名规范。数学界未来的核心危机是人类专家共享理解与数学文化的断层，应对策略应从垄断定理发现转向奖励对机器成果的梳理、消化与阐释。","format":"magazine","added":"2026-09-24","originalDate":"2026-07-27","tags":["思想与人文","人工智能","数学研究","莱顿宣言"],"studioId":"c1a2cca14766afe2579c9369110c7fa1a375536df46a0e3aba6a1f48b945143a"},{"slug":"open-mathematics-in-the-ai-era","title":"AI时代数学开放文化的危机重塑与跨界机遇","summary":"探讨AI快速证明能力对数学界传统开放分享文化的冲击，借鉴生物学基因组数据共享协定经验，呼吁学术界重构科研声誉与信用分配机制，并在机器辅助时代转向跨学科复杂现象以探索崭新的数学前沿。","format":"magazine","added":"2026-09-24","originalDate":"2026-09-22","tags":["思想与人文","人工智能","数学研究","学术生态"],"studioId":"ba96239245ece54a44c9e8442b8084b29f616f18b324ac7e22f9d01fbf848524"},{"slug":"trust-and-understanding-in-scientific-ai","title":"科学工程中的AI信任：从黑箱预测走向可审计因果链","summary":"文章指出在气候预测与飞机设计等难以即时验证的领域，单纯黑箱预测无法建立信任。必须将AI嵌入守恒律等物理机理支架中，构建可独立审计的因果链条，才能兼顾预测实用性与深层因果理解。","format":"magazine","added":"2026-09-24","originalDate":"2026-09-24","tags":["AI","科学智能","流体力学","气候模型"],"studioId":"e6245d810ee8f7940ac1e4f1be29ebb322a2f6145638cb0ae5214f8a1c95b2f0"},{"slug":"what-sort-of-maths-are-llms-good-at","title":"大模型擅长哪些数学：反例构造与机器直觉的边界","summary":"高尔斯指出大模型擅长反例与存在性构造，本质依托广博知识与高速暴力尝试；但在需要深刻数学直觉、大幅剪枝的复杂定理证明中仍不及人类，未来真正的质变标志在于能否独立产出具有高度原创性与概念深度的新方法。","format":"magazine","added":"2026-09-24","originalDate":"2026-08-12","tags":["AI","大语言模型","反例构造","自动定理证明"],"studioId":"a4a02e17a01dd1bbf289a3aec16a44a558410389f17a6763c6b2fbdaf3327ba9"},{"slug":"why-gowers-declined-fields-letter","title":"为何拒签菲尔兹得主公开信：高尔斯论数学传承危机","summary":"数学家高尔斯阐明拒签菲尔兹得主公开信的缘由，指出AI冲击下的核心危机并非定理生成过载或概念理解退化，而是青年学者研究动机瓦解、人才培养断代以及资助流失所带来的数学共同体传承危机。","format":"magazine","added":"2026-09-24","originalDate":"2026-09-17","tags":["思想与人文","人工智能","数学研究","学术共同体"],"studioId":"85fe531031cf061bdbb6650295fefda307a73467b6a25ae971812f3eb3652515"},{"slug":"why-we-need-human-mathematicians","title":"AI时代为何仍需人类数学家：掌控权与人类繁荣","summary":"面对AI带来的职业危机，罗博深提出以人类繁荣为首要公理。他论证黑箱AI的扩散将产生海量不可信决策与控制点，唯有扎根前沿的专业人类才能掌握方向盘，而合格监管专家的严重匮乏也将倒逼AI研发被迫减速。","format":"magazine","added":"2026-09-24","originalDate":"2026-09-20","tags":["思想与人文","人工智能","数学研究","AI安全"],"studioId":"879ca00d696205a1e538e4adbdff4b152dfaf5a6d3f1eb0e886f86c41a74ffa1"}]'),i=[{id:"magazine",label:"特刊"},{id:"poster",label:"海报"},{id:"deck",label:"幻灯片"}],m=s,r=a=>"/cards/".concat(a.slug),o=a=>"".concat(t.o2,"/card-art/").concat(a.slug,".html"),g=a=>"".concat(t.o2,"/card-art/").concat(a.slug,".webp");function l(a){return i.find(e=>e.id===a.format).label}},765:()=>{}}]);